// Copy the OpenAPI spec generated by the ORQO app into public/openapi.json.
// Source: ORQO_OPENAPI (a file path or URL), default ../orqo-nv/openapi.json.
import { readFile, writeFile } from 'node:fs/promises';

const source = process.env.ORQO_OPENAPI ?? '../orqo-nv/openapi.json';
const text = /^https?:\/\//.test(source)
  ? await (await fetch(source)).text()
  : await readFile(source, 'utf8');

const spec = JSON.parse(text);
if (!spec.openapi || !spec.paths) throw new Error(`${source} is not an OpenAPI document`);

await writeFile('public/openapi.json', `${JSON.stringify(spec, null, 2)}\n`);
console.log(`public/openapi.json <- ${source} (${Object.keys(spec.paths).length} paths, v${spec.info?.version})`);
